'use strict';
const $=id=>document.getElementById(id),canvas=$('battleCanvas'),ctx=canvas.getContext('2d');
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const images={};for(const name of ['watcher','deep-one','cthulhu',...HEROES.map(h=>h.art)]){const img=new Image();img.src=HEROES.some(h=>h.art===name)?`assets/${name}-v2.jpg`:`assets/${name}.svg`;images[name]=img;}
let game,aim=null,keyboardAngle=-Math.PI/2,paused=false,particles=[],floaters=[],beams=[],rings=[],trail=[],shake=0,lastTime=0,accumulator=0,uiDirty=true;
let sound=true,audioContext=null,messageTimer,toastTimer,resultTimer,best=0,modalType='';
try{best=Number(localStorage.getItem('abyssal-best-v1'))||0;const savedSound=localStorage.getItem('abyssal-sound-v1');if(savedSound!==null)sound=savedSound==='true';}catch{}
const portraitPosition=id=>`${id%2?100:0}% ${id>1?100:0}%`;
const log=[];const soundIcon=on=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 9h4l5-4v14l-5-4H4z"/>${on?'<path d="M16 8q5 4 0 8m3-11q8 7 0 14"/>':'<path d="m17 9 5 6m0-6-5 6"/>'}</svg>`;
function updateSound(){ $('soundButton').innerHTML=soundIcon(sound);$('soundButton').setAttribute('aria-label',sound?'关闭音效':'开启音效');$('soundButton').title=sound?'关闭音效':'开启音效';}
function tone(freq=220,duration=.08,type='sine',volume=.04){
  if(!sound)return;try{if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.6),audioContext.currentTime+duration);g.gain.setValueAtTime(volume,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration);}catch{}
}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2400);}
function message(text,duration=1700){$('battleMessage').textContent=text;$('battleMessage').classList.add('visible');clearTimeout(messageTimer);messageTimer=setTimeout(()=>$('battleMessage').classList.remove('visible'),duration);}
function addLog(text){log.unshift({turn:game?game.turn:1,text});if(log.length>5)log.pop();$('battleLog').innerHTML=log.map(l=>`<li><span>${String(l.turn).padStart(2,'0')}</span><div>${l.text}</div></li>`).join('');}
function burst(x,y,color,count=16){if(reduced)count=5;for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,speed=25+Math.random()*140;particles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:.3+Math.random()*.45,max:.75,color,size:1+Math.random()*2});}}
function event(e){
  uiDirty=true;
  if(typeof BattleFX!=='undefined')BattleFX.event(e);
  if(e.type==='stage'){$('comboDisplay').classList.remove('visible');$('comboRating').textContent='';particles=[];beams=[];trail=[];rings=[];floaters=[];if(game){addLog(`抵达${STAGES[e.stage].name}。调查开始。`);message(STAGES[e.stage].name);}}
  if(e.type==='launch'){aim=null;trail=[];$('aimHelp').style.display='none';$('comboDisplay').classList.remove('visible');tone(170,.15,'triangle');addLog(`${HEROES[e.hero].name}发起弹射。`);}
  if(e.type==='hit'){burst(e.x,e.y,e.kind==='support'?'#a4d9cf':'#e2cd8c');floaters.push({x:e.x+(Math.random()-.5)*30,y:e.y-25,text:String(e.amount),color:e.kind==='support'?'#b8e5dd':'#e4d3a0',life:1,max:1});$('comboDisplay').classList.add('visible');$('comboDisplay').querySelector('strong').textContent=e.combo;shake=reduced?0:3;tone(230+e.combo*32,.07,'triangle',.035);}
  if(e.type==='kill'){burst(e.x,e.y,'#9cbd8a',35);rings.push({x:e.x,y:e.y,r:20,life:.65,max:.65,color:'#bfd19c'});addLog(`${e.name}已被驱散。`);tone(90,.2,'sine',.05);}
  if(e.type==='support'){const h=HEROES[e.hero];rings.push({x:e.x,y:e.y,r:25,life:.5,max:.5,color:h.color});floaters.push({x:e.x,y:e.y-35,text:h.skill,color:h.color,life:1.4,max:1.4});addLog(`援护 · ${h.name}「${h.skill}」`);tone(530,.12,'sine');}
  if(e.type==='beam')beams.push({x1:e.from.x,y1:e.from.y,x2:e.to.x,y2:e.to.y,color:e.color,life:.28,max:.28});
  if(e.type==='heal'){floaters.push({x:e.x,y:e.y-60,text:`+${e.amount}`,color:'#badfa8',life:1.2,max:1.2});}
  if(e.type==='wall'){burst(e.x,e.y,'#8ba894',4);tone(110,.035,'sine',.018);}
  if(e.type==='ultimate'){message('古 印 解 放',1500);rings.push({x:e.x,y:e.y,r:35,life:1.2,max:1.2,color:'#e5e5a5'});burst(e.x,e.y,'#d8e6a7',50);tone(70,.7,'sine',.07);addLog('古印解放：全场净化，弹射伤害提升。');}
  if(e.type==='armed'){toast(e.armed?'古印已就绪：下一次弹射释放秘术':'已取消秘术，能量保留');}
  if(e.type==='enemyAttack'){beams.push({x1:e.x,y1:e.y,x2:game.current.x,y2:game.current.y,color:'#ce8276',life:.4,max:.4});shake=reduced?0:6;tone(65,.22,'sawtooth',.025);}
  if(e.type==='madness')addLog('理智低于 30，侵蚀额外损失 160 生命。');
  if(e.type==='turn'){if(e.damage){addLog(`敌方反击，小队受到 ${e.damage} 伤害。`);message(`敌方反击 −${e.damage}`,1100);}else{addLog('敌人仍在蓄力，轮到下一位调查员。');}setTimeout(()=>{if(game.mode==='ready')$('comboDisplay').classList.remove('visible');},1300);keyboardAngle=-Math.PI/2;}
  if(['cleared','victory','defeat'].includes(e.type)){if(e.type==='victory')game.score+=Math.round(game.hp/4)+game.sanity*10;saveBest();clearTimeout(resultTimer);resultTimer=setTimeout(()=>showResult(),750);}
}
function saveBest(){if(game.score>best){best=game.score;try{localStorage.setItem('abyssal-best-v1',String(best));}catch{}}}
function updateUI(){
  if(!game)return;const s=STAGES[game.stage];$('stageName').textContent=s.name;$('stageCount').textContent=`0${game.stage+1} / 03`;$('turnLabel').textContent=`回合 ${String(game.turn).padStart(2,'0')}`;
  $('enemyTitle').textContent=s.title;$('enemyHealthText').textContent=`${game.stageHp.toLocaleString()} / ${game.stageMaxHp.toLocaleString()}`;$('enemyHealthBar').style.width=`${game.stageHp/game.stageMaxHp*100}%`;$('bossTag').textContent=game.stage===2?'FINAL BOSS · 封印旧日支配者':'消灭所有异变生物';
  $('partyHealthText').textContent=`${game.hp.toLocaleString()} / 8,000`;$('partyHealthBar').style.width=`${game.hp/80}%`;$('partyHealthBar').style.background=game.hp<2000?'#bd7765':'';$('sanityText').textContent=game.sanity;$('sanityText').style.color=game.sanity<30?'#d6937f':'';
  $('currentName').textContent=game.mode==='moving'?'调查员行动中…':`${HEROES[game.active].name}的回合`;$('shotHint').textContent=game.armed?'古印已就绪 · 拖拽释放':game.mode==='moving'?'碰撞敌人 · 触发援护':'瞄准 · 弹射 · 连锁';
  $('ultimateText').textContent=game.armed?'已就绪 · 再次点击取消':game.energy>=100?'秘术已就绪':'秘术充能 '+game.energy+'%';$('ultimateButton').disabled=game.energy<100||game.mode!=='ready';$('ultimateButton').classList.toggle('ready',game.energy>=100);$('ultimateButton').setAttribute('aria-pressed',String(game.armed));
  $('objectiveTitle').textContent=s.objective;$('objectiveDescription').textContent=s.description;$('rewardValue').textContent=s.reward.toLocaleString();
  document.querySelector('.arena-location span').textContent=s.place;$('bestScore').textContent=best?best.toLocaleString():'—';
  $('route').innerHTML=STAGES.map((s,i)=>`<div class="route-step ${i===game.stage?'active':i<game.stage?'complete':''}"><div class="route-number"><span>${i<game.stage?'✓':String(i+1).padStart(2,'0')}</span></div><div><strong>${s.name}</strong><small>${i<game.stage?'调查完成':i===game.stage?'正在调查':s.subtitle.split(' · ')[0]}</small></div></div>`).join('');
  $('squad').innerHTML=HEROES.map((h,i)=>`<button class="character-card ${i===game.active?'active':''}" style="--character-color:${h.color};--portrait-position:${portraitPosition(i)};--portrait-image:url('assets/${h.art}-v2.jpg')" data-hero="${i}" aria-label="查看${h.name}的援护技能${i===game.active?'，当前回合':''}"><span class="portrait"></span><span class="card-stars">★★★★★</span><span class="element">${['✦','✧','☀','☾'][i]}</span><span class="card-label"><strong>${h.name}</strong><small>${h.type} · ${h.role}</small></span></button>`).join('');
  if($('enemyHealthLag'))$('enemyHealthLag').style.width=`${game.stageHp/game.stageMaxHp*100}%`;
  if($('ultimateFill'))$('ultimateFill').style.width=`${game.energy}%`;
  if($('featurePortrait')){$('featurePortrait').style.setProperty('--portrait-image',`url("assets/${HEROES[game.active].art}-v2.jpg")`);$('featureName').textContent=HEROES[game.active].name;$('featureRole').textContent=HEROES[game.active].role;}
  uiDirty=false;
}
function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*500/r.width,y:(e.clientY-r.top)*560/r.height};}
function startAim(e){if(e.button!==undefined&&e.button!==0)return;if(paused||game.mode!=='ready')return;const p=point(e),b=game.current;if(Math.hypot(p.x-b.x,p.y-b.y)>54){toast('请按住发光的调查员，向后拖动');return;}canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);aim={pointer:e.pointerId,start:p,end:p};e.preventDefault();tone(310,.035);}
function moveAim(e){if(!aim||aim.pointer!==e.pointerId)return;aim.end=point(e);e.preventDefault();}
function endAim(e){if(!aim||aim.pointer!==e.pointerId)return;const a=aim;aim=null;try{canvas.releasePointerCapture(e.pointerId);}catch{}const dx=a.start.x-a.end.x,dy=a.start.y-a.end.y,length=Math.hypot(dx,dy);if(length<12)return;game.launch(dx,dy,Math.min(length/110,1));}
function cancelAim(){aim=null;}
canvas.addEventListener('pointerdown',startAim);canvas.addEventListener('pointermove',moveAim);canvas.addEventListener('pointerup',endAim);canvas.addEventListener('pointercancel',cancelAim);canvas.addEventListener('lostpointercapture',cancelAim);canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('keydown',e=>{if(paused||game.mode!=='ready')return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')keyboardAngle-=.09;if(e.key==='ArrowRight')keyboardAngle+=.09;if(e.key==='ArrowUp')keyboardAngle=-Math.PI/2;if(e.key==='ArrowDown')keyboardAngle=Math.PI/2;if(e.key.startsWith('Arrow')){const b=game.current;aim={keyboard:true,start:{x:b.x,y:b.y},end:{x:b.x-Math.cos(keyboardAngle)*100,y:b.y-Math.sin(keyboardAngle)*100}};}if(e.key===' '){game.launch(Math.cos(keyboardAngle),Math.sin(keyboardAngle),1);aim=null;}if(e.key.toLowerCase()==='r')game.armUltimate();});
function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function circle(x,y,r,fill,stroke,width=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.lineWidth=width;ctx.strokeStyle=stroke;ctx.stroke();}}
function drawAim(t){
  const b=game.current;if(!aim)return;let dx=aim.start.x-aim.end.x,dy=aim.start.y-aim.end.y,len=Math.hypot(dx,dy);if(len<5)return;dx/=len;dy/=len;
  let px=b.x,py=b.y;ctx.save();ctx.setLineDash([4,8]);ctx.lineDashOffset=-t*20;ctx.lineWidth=2;ctx.strokeStyle=game.armed?'#ecdfa8aa':'#cce6b9a6';ctx.beginPath();ctx.moveTo(px,py);
  for(let step=0;step<100;step++){let nx=px+dx*5,ny=py+dy*5;if(nx<34||nx>466){dx*=-1;nx=clamp(nx,34,466);}if(ny<102||ny>513){dy*=-1;ny=clamp(ny,102,513);}px=nx;py=ny;ctx.lineTo(px,py);if(game.enemies.some(e=>e.hp>0&&Math.hypot(px-e.x,py-e.y)<e.r+22)||game.pillars.some(p=>Math.hypot(px-p.x,py-p.y)<p.r+22))break;}
  ctx.stroke();ctx.setLineDash([]);circle(px,py,5,'#e0eac5');const drag=Math.min(len,112);line(b.x,b.y,b.x-(aim.start.x-aim.end.x)/len*drag,b.y-(aim.start.y-aim.end.y)/len*drag,'#c1d2ac55',2);circle(b.x-(aim.start.x-aim.end.x)/len*drag,b.y-(aim.start.y-aim.end.y)/len*drag,6,null,'#c1d2ac77');ctx.restore();
}
function draw(t,dt){
  ctx.clearRect(0,0,500,560);ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake=Math.max(0,shake-dt*25);}
  if(!reduced){for(let i=0;i<15;i++){const x=(i*137.3+Math.sin(t*.14+i)*20)%500,y=(i*87+t*(3+i%3))%560;circle(x,y,.6+(i%3)*.3,`rgba(192,214,153,${.13+Math.sin(t+i)*.09})`);}}
  for(const p of game.pillars){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.PI/4);ctx.fillStyle='#23382f';ctx.strokeStyle='#6e805c88';ctx.lineWidth=1;ctx.fillRect(-14,-14,28,28);ctx.strokeRect(-14,-14,28,28);ctx.strokeStyle='#c8c28b44';ctx.strokeRect(-9,-9,18,18);ctx.restore();line(p.x-5,p.y,p.x+5,p.y,'#b5bc7b55');line(p.x,p.y-5,p.x,p.y+5,'#b5bc7b55');}
  for(const e of game.enemies){if(e.hp<=0)continue;const offset=reduced?0:Math.sin(t*1.6+e.id)*3;const size=e.r*(e.art==='deep-one'?2.7:3.1),gradient=ctx.createRadialGradient(e.x,e.y,5,e.x,e.y,e.r*1.35);gradient.addColorStop(0,'#a2c98c18');gradient.addColorStop(1,'#9ebd7f00');circle(e.x,e.y,e.r*1.35,gradient);ctx.save();ctx.shadowColor='#06100d';ctx.shadowBlur=15;ctx.shadowOffsetY=5;if(images[e.art].complete&&images[e.art].naturalWidth)ctx.drawImage(images[e.art],e.x-size/2,e.y-size/2+offset,size,size);else circle(e.x,e.y,e.r,'#466951','#a4bd8b');ctx.restore();if(e.flash>0){circle(e.x,e.y,e.r,`rgba(218,233,163,${e.flash*1.5})`);}const by=e.y+e.r+9;ctx.fillStyle='#0e201e';ctx.fillRect(e.x-e.r*.55,by,e.r*1.1,3);ctx.fillStyle=e.art==='cthulhu'?'#c39c73':'#a1b680';ctx.fillRect(e.x-e.r*.55,by,e.r*1.1*e.hp/e.maxHp,3);circle(e.x+e.r*.82,e.y-e.r*.65,11,'#15251f','#c0ad6d99');ctx.textAlign='center';ctx.fillStyle=e.counter===1?'#e1a88b':'#e0d4a2';ctx.font='bold 11px "Space Grotesk",sans-serif';ctx.fillText(e.counter,e.x+e.r*.82,e.y-e.r*.65+4);}
  drawAim(t);
  if(game.mode==='moving'){trail.push({x:game.current.x,y:game.current.y});if(trail.length>22)trail.shift();}else if(trail.length)trail.shift();for(let i=1;i<trail.length;i++)line(trail[i-1].x,trail[i-1].y,trail[i].x,`rgba(196,222,165,${i/trail.length*.35})`,i/trail.length*11);
  for(const h of game.heroes){const active=h.id===game.active;if(active){const pulse=reduced?0:Math.sin(t*3)*2;circle(h.x,h.y,33+pulse,null,game.armed?'#efe3a0b0':'#b7d49799',1);circle(h.x,h.y,38+pulse,null,'#c2db9c24',1);ctx.save();ctx.translate(h.x,h.y);ctx.rotate(t*.4);ctx.strokeStyle='#d0e8ac';ctx.lineWidth=2;for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);line(0,-35,0,-40,'#d0e8ac',2);}ctx.restore();if(game.mode==='ready'){ctx.fillStyle='#d0e3b5';ctx.beginPath();ctx.moveTo(h.x-4,h.y-46);ctx.lineTo(h.x+4,h.y-46);ctx.lineTo(h.x,h.y-41);ctx.fill();}}
    ctx.save();ctx.shadowBlur=active?18:8;ctx.shadowColor=active?'#a9cf8077':'#0009';circle(h.x,h.y,h.r+2,'#14261f',active?'#d6e9b5':h.color,active?2:1);ctx.beginPath();ctx.arc(h.x,h.y,h.r,0,Math.PI*2);ctx.clip();if(images[h.art].complete&&images[h.art].naturalWidth)ctx.drawImage(images[h.art],h.x-h.r,h.y-h.r,h.r*2,h.r*2);ctx.restore();circle(h.x+16,h.y+16,7,'#172d25',h.color,.7);ctx.fillStyle=h.color;ctx.font='8px sans-serif';ctx.textAlign='center';ctx.fillText(h.id+1,h.x+16,h.y+19);
  }
  for(const b of beams){ctx.globalAlpha=b.life/b.max;ctx.shadowBlur=10;ctx.shadowColor=b.color;line(b.x1,b.y1,b.x2,b.y2,b.color,2);ctx.shadowBlur=0;b.life-=dt;}beams=beams.filter(b=>b.life>0);ctx.globalAlpha=1;
  for(const r of rings){r.r+=dt*160;r.life-=dt;ctx.globalAlpha=Math.max(0,r.life/r.max);circle(r.x,r.y,r.r,null,r.color,2);}rings=rings.filter(r=>r.life>0);ctx.globalAlpha=1;
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy*=.98;p.life-=dt;ctx.globalAlpha=Math.max(0,p.life/p.max);circle(p.x,p.y,p.size,p.color);}particles=particles.filter(p=>p.life>0);ctx.globalAlpha=1;
  for(const f of floaters){f.y-=dt*30;f.life-=dt;ctx.globalAlpha=Math.min(1,Math.max(0,f.life*3));ctx.fillStyle=f.color;ctx.font=/^\d+$/.test(f.text)?'600 20px "Space Grotesk",sans-serif':'12px "Microsoft YaHei",sans-serif';ctx.textAlign='center';ctx.shadowColor='#06100c';ctx.shadowBlur=5;ctx.fillText(f.text,f.x,f.y);ctx.shadowBlur=0;}floaters=floaters.filter(f=>f.life>0);ctx.globalAlpha=1;ctx.restore();
}
function frame(ms){const dt=Math.min((ms-lastTime)/1000||0,.05);lastTime=ms;if(!paused){let stepTime=dt;if(typeof BattleFX!=='undefined')stepTime=BattleFX.physicsTime(dt);accumulator+=stepTime;while(accumulator>=1/120){game.update(1/120);accumulator-=1/120;if(typeof BattleFX!=='undefined'&&BattleFX.hitStop>0){accumulator=0;break;}}draw(ms/1000,dt);}else{accumulator=0;}if(uiDirty)updateUI();requestAnimationFrame(frame);}
function resizeCanvas(){const ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(500*ratio);canvas.height=Math.round(560*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);draw(performance.now()/1000,0);}
function openModal(type,content){aim=null;paused=true;modalType=type;$('modalContent').innerHTML=content;if(!$('modal').open)$('modal').showModal();$('closeModal').style.display=['result'].includes(type)?'none':'';}
function closeModal(){if(modalType==='result')return;$('modal').close();paused=false;lastTime=performance.now();modalType='';canvas.focus({preventScroll:true});}
function showGuide(){openModal('guide',`<div class="modal-kicker">INVESTIGATOR'S HANDBOOK</div><h2>每一次弹射，都是反击。</h2><div class="guide-steps"><div class="guide-step"><b>01</b><div><strong>向后拉，向前出发</strong><p>按住发光的调查员，朝目标的反方向拖动。松手发射，拉得越远，速度越快。虚线显示首次碰撞前的路线。</p></div></div><div class="guide-step"><b>02</b><div><strong>撞击敌人，也要触碰同伴</strong><p>墙壁与敌人会让弹珠反弹；触碰同伴触发援护，每位同伴每回合一次。敌人头上的数字是反击倒计时。</p></div></div><div class="guide-step"><b>03</b><div><strong>在理智耗尽前，解放古印</strong><p>命中、援护和回合结束会积攒秘术。能量达到 100% 后点击「古印解放」，下一发将净化全场并造成 2.2 倍碰撞伤害。生命或理智归零则调查失败。</p></div></div></div><p class="modal-note">键盘：点击战场后，← → 调整角度，↑ ↓ 重置方向，空格发射，R 切换秘术。点击角色卡可查看技能。</p><div class="modal-actions"><button class="primary-button" data-action="resume">我准备好了 <span>↗</span></button></div>`);}
function showInvestigators(id){const heroes=id===undefined?HEROES:[HEROES[id]];openModal('investigators',`<div class="modal-kicker">THE MISKATONIC FOUR</div><h2>${id===undefined?'最后的调查小队':heroes[0].name}</h2><p>调查员按顺序行动。弹射途中触碰队友，即可发动对应援护。</p>${heroes.map(h=>`<div class="profile"><div class="profile-portrait" role="img" aria-label="${h.name}" style="--portrait-position:${portraitPosition(HEROES.indexOf(h))};--portrait-image:url('assets/${h.art}-v2.jpg')"></div><div><div class="profile-type">${h.role} / ${h.type} / 攻击 ${h.attack}</div><h3>${h.name} · ${h.skill}</h3><p>${h.description}</p><p class="modal-note">${h.lore}</p></div></div>`).join('')}<div class="modal-actions"><button class="primary-button" data-action="resume">返回战场</button></div>`);}
function showArchive(){openModal('archive',`<div class="modal-kicker">CLASSIFIED · DEEP SEA ARCHIVES</div><h2>深渊不会遗忘。</h2><p>1926 年，密斯卡托尼克大学收到了一封来自印斯茅斯的求救信。信纸始终潮湿，字迹却在夜里自行改变。</p>${STAGES.map((s,i)=>`<div class="profile"><img src="assets/${i===0?'deep-one-v2':'boss-v2'}.png" alt=""><div><div class="profile-type">CHAPTER 0${i+1} / ${s.place}</div><h3>${s.name}</h3><p>${s.description}</p></div></div>`).join('')}<p class="modal-note">本地最佳残响：${best?best.toLocaleString():'尚无记录'}。分数保存在当前浏览器。<br>原创单人弹射游戏 · 三章完整调查 · 无需注册游戏账号。</p><div class="modal-actions"><button class="primary-button" data-action="resume">继续调查</button></div>`);}
function showPause(){if(['cleared','victory','defeat'].includes(game.mode)){showResult();return;}openModal('pause',`<div class="modal-kicker">A MOMENT OF SILENCE</div><h2>让灯火，再亮一会儿。</h2><p>调查已暂停。${STAGES[game.stage].name} · 第 ${game.turn} 回合</p><div class="result-stats"><div><strong>${game.hp}</strong><span>小队生命</span></div><div><strong>${game.sanity}</strong><span>剩余理智</span></div><div><strong>${game.score}</strong><span>旧日残响</span></div></div><div class="modal-actions"><button class="secondary-button" data-action="confirm-restart">重新调查</button><button class="primary-button" data-action="resume">继续行动</button></div>`);}
function showResult(){
  const cleared=game.mode==='cleared',won=game.mode==='victory';if(!cleared&&!won&&game.mode!=='defeat')return;
  openModal('result',`<div class="modal-kicker">${cleared?'CHAPTER COMPLETE':won?'THE SEAL IS RESTORED':'EXPEDITION LOST'}</div><div class="result-symbol">${cleared?'◇':won?'✧':'☾'}</div><h2 class="result-title">${cleared?'迷雾背后，还有更深的海。':won?'长夜将尽，群星沉寂。':'深渊记住了你的名字。'}</h2><p style="text-align:center">${cleared?`${STAGES[game.stage].name}调查完成。<br>进入下一章，恢复 1,000 生命与 15 点理智。`:won?'古印重新闭合，旧日之神回归长眠。<br>调查员们，欢迎回到有光的世界。':game.hp<=0?'小队生命耗尽。借助露西亚的援护恢复生命，再次向深渊出发。':'理智已经耗尽。善用援护和古印，尽快结束战斗。'}</p><div class="result-stats"><div><strong>${game.score.toLocaleString()}</strong><span>旧日残响</span></div><div><strong>${game.maxCombo}</strong><span>最高连击</span></div><div><strong>${game.totalShots}</strong><span>弹射次数</span></div></div><div class="modal-actions"><button class="primary-button" data-action="${cleared?'next-stage':'restart'}">${cleared?'深入下一章 ↗':'再次出发 ↗'}</button></div>`);
}
function restart(){clearTimeout(resultTimer);clearTimeout(messageTimer);$('modal').close();paused=false;modalType='';particles=[];floaters=[];beams=[];rings=[];trail=[];shake=0;aim=null;log.length=0;game.reset();$('aimHelp').style.display='';$('comboDisplay').classList.remove('visible');uiDirty=true;canvas.focus({preventScroll:true});}
document.addEventListener('click',e=>{
  const card=e.target.closest('[data-hero]');if(card){showInvestigators(Number(card.dataset.hero));return;}
  const el=e.target.closest('[data-action]');if(!el)return;
  switch(el.dataset.action){case'guide':showGuide();break;case'investigators':showInvestigators();break;case'archive':showArchive();break;case'battle':document.querySelector('.battle-column').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'});break;case'resume':closeModal();break;case'next-stage':$('modal').close();paused=false;modalType='';game.nextStage();uiDirty=true;canvas.focus({preventScroll:true});break;case'restart':restart();break;case'confirm-restart':openModal('confirm',`<div class="modal-kicker">RESTART EXPEDITION</div><h2>重新启程？</h2><p>当前调查进度将重置，已保存的最佳记录会保留。</p><div class="modal-actions"><button class="secondary-button" data-action="resume">继续当前调查</button><button class="primary-button" data-action="restart">重新开始</button></div>`);break;}
});
$('soundButton').addEventListener('click',()=>{sound=!sound;updateSound();try{localStorage.setItem('abyssal-sound-v1',String(sound));}catch{}tone(440,.13);toast(sound?'音效已开启':'音效已关闭');});
$('ultimateButton').addEventListener('click',()=>game.armUltimate());$('pauseButton').addEventListener('click',showPause);$('closeModal').addEventListener('click',closeModal);
$('modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal();});
document.addEventListener('visibilitychange',()=>{aim=null;if(document.hidden&&!paused&&['ready','moving'].includes(game.mode))showPause();});window.addEventListener('blur',cancelAim);window.addEventListener('resize',resizeCanvas);
game=new AbyssEngine(event);addLog('调查小队抵达雾港。保持理智。');addLog('拖动伊芙琳，发起第一次弹射。');updateSound();updateUI();resizeCanvas();requestAnimationFrame(frame);
